import React, { type JSX } from "react";
import { createRootRoute, createRoute, createRouter, Link, Outlet, useNavigate, useParams } from "@tanstack/react-router";
import { Activity, ArrowLeft, Check, ChevronRight, CircleHelp, Copy, Database, ExternalLink, GitBranch, LayoutDashboard, Menu, Moon, PanelLeft, Radio, Search, Send, Settings, Square, Sun, X, FileArchive, Wrench, Code2, Network } from "lucide-react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { api, ApiClientError, subscribeToChatStream, subscribeToEvents } from "./lib/api";
import { formatDate, formatNumber, formatRelative } from "./lib/format";
import { useUiStore, type ThemePreference } from "./lib/ui-store";
import { Badge, Button, Card, CardBody, CardHeader, CopyableId, EmptyState, ErrorState, Label, Skeleton, StatusBadge, StatusDot } from "./components/ui";
import type { ChatActivity, ChatMessageDto, ChatStreamEventDto, ContextInspectorDto, RetrievalInspectorDto, RuntimeEventDto, SessionSummaryDto } from "@mnemos/contracts";
import { AgentsPage, ArtifactsPage, DashboardPage, OperationsPage, PtcPage, TasksPage, ToolsPage } from "./advanced";

const rootRoute = createRootRoute({ component: AppShell, notFoundComponent: NotFoundPage });
const overviewRoute = createRoute({ getParentRoute: () => rootRoute, path: "/", component: DashboardPage });
const sessionsRoute = createRoute({ getParentRoute: () => rootRoute, path: "/sessions", component: SessionsPage });
const sessionRoute = createRoute({ getParentRoute: () => rootRoute, path: "/sessions/$sessionId", component: SessionPage });
const historyRoute = createRoute({ getParentRoute: () => rootRoute, path: "/sessions/$sessionId/history/$messageId", component: HistorySourcePage });
const memoryRoute = createRoute({ getParentRoute: () => rootRoute, path: "/memory", component: MemoryPage });
const eventsRoute = createRoute({ getParentRoute: () => rootRoute, path: "/events", component: EventsPage });
const settingsRoute = createRoute({ getParentRoute: () => rootRoute, path: "/settings", component: SettingsPage });
const artifactsRoute = createRoute({ getParentRoute: () => rootRoute, path: "/artifacts", component: ArtifactsPage });
const toolsRoute = createRoute({ getParentRoute: () => rootRoute, path: "/tools", component: ToolsPage });
const ptcRoute = createRoute({ getParentRoute: () => rootRoute, path: "/ptc", component: PtcPage });
const agentsRoute = createRoute({ getParentRoute: () => rootRoute, path: "/agents", component: AgentsPage });
const tasksRoute = createRoute({ getParentRoute: () => rootRoute, path: "/tasks", component: TasksPage });
const operationsRoute = createRoute({ getParentRoute: () => rootRoute, path: "/operations", component: OperationsPage });
const routeTree = rootRoute.addChildren([overviewRoute, sessionsRoute, sessionRoute, historyRoute, memoryRoute, eventsRoute, settingsRoute, artifactsRoute, toolsRoute, ptcRoute, agentsRoute, tasksRoute, operationsRoute]);
export const router = createRouter({ routeTree, defaultPreload: "intent" });
declare module "@tanstack/react-router" { interface Register { router: typeof router; } }

export function AppShell(): JSX.Element {
  const collapsed = useUiStore((state) => state.sidebarCollapsed); const mobileOpen = useUiStore((state) => state.mobileNavOpen);
  const setMobileOpen = useUiStore((state) => state.setMobileNavOpen); const toggleSidebar = useUiStore((state) => state.toggleSidebar);
  const theme = useUiStore((state) => state.theme); const setTheme = useUiStore((state) => state.setTheme);
  const ready = useQuery({ queryKey: ["ready"], queryFn: api.ready, refetchInterval: 15_000 });
  const runtimeStatus = ready.data?.status === "ok" ? "ready" : ready.isError ? "not_ready" : "reconnecting";
  return <div className="min-h-screen bg-canvas text-ink">
    <aside className={`fixed inset-y-0 left-0 z-30 flex w-64 flex-col border-r border-line bg-panel transition-transform duration-200 lg:translate-x-0 ${collapsed ? "lg:w-[72px]" : ""} ${mobileOpen ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="flex h-16 items-center justify-between border-b border-line px-4"><Link to="/" className="flex items-center gap-3 rounded-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-400/80" onClick={() => setMobileOpen(false)}><span className="grid h-8 w-8 place-items-center rounded-md bg-ink text-sm font-black tracking-[-0.1em] text-amber-300">M·</span>{!collapsed ? <span><span className="block text-sm font-bold tracking-tight">Mnemos</span><span className="block text-[10px] uppercase tracking-[0.2em] text-ink-muted">Runtime console</span></span> : null}</Link><button type="button" aria-label="Close navigation" onClick={() => setMobileOpen(false)} className="rounded-md p-2 text-ink-muted hover:bg-ink/5 lg:hidden"><X size={18} /></button></div>
      <nav aria-label="Primary" className="flex-1 space-y-1 overflow-y-auto px-3 py-5"><NavItem to="/" label="Overview" icon={<LayoutDashboard size={17} />} collapsed={collapsed} onNavigate={() => setMobileOpen(false)} /><NavItem to="/sessions" label="Sessions" icon={<Database size={17} />} collapsed={collapsed} onNavigate={() => setMobileOpen(false)} /><NavItem to="/memory" label="Memory" icon={<Search size={17} />} collapsed={collapsed} onNavigate={() => setMobileOpen(false)} /><NavItem to="/artifacts" label="Artifacts" icon={<FileArchive size={17} />} collapsed={collapsed} onNavigate={() => setMobileOpen(false)} /><NavItem to="/tools" label="Tools" icon={<Wrench size={17} />} collapsed={collapsed} onNavigate={() => setMobileOpen(false)} /><NavItem to="/ptc" label="PTC" icon={<Code2 size={17} />} collapsed={collapsed} onNavigate={() => setMobileOpen(false)} /><NavItem to="/agents" label="Agents" icon={<Network size={17} />} collapsed={collapsed} onNavigate={() => setMobileOpen(false)} /><NavItem to="/tasks" label="Tasks" icon={<GitBranch size={17} />} collapsed={collapsed} onNavigate={() => setMobileOpen(false)} /><NavItem to="/operations" label="Operations" icon={<Activity size={17} />} collapsed={collapsed} onNavigate={() => setMobileOpen(false)} /><NavItem to="/events" label="Events" icon={<Radio size={17} />} collapsed={collapsed} onNavigate={() => setMobileOpen(false)} /></nav>
      <div className="border-t border-line p-3"><NavItem to="/settings" label="Settings" icon={<Settings size={17} />} collapsed={collapsed} onNavigate={() => setMobileOpen(false)} />{!collapsed ? <div className="mt-3 rounded-lg bg-canvas px-3 py-3"><div className="flex items-center gap-2"><StatusDot status={runtimeStatus} /><span className="text-xs font-semibold">{runtimeStatus === "ready" ? "Runtime ready" : runtimeStatus === "not_ready" ? "Runtime unavailable" : "Connecting"}</span></div><p className="mt-1 text-[11px] text-ink-muted">Console · F3</p></div> : null}</div>
    </aside>
    {mobileOpen ? <button type="button" aria-label="Close navigation overlay" className="fixed inset-0 z-20 bg-black/30 lg:hidden" onClick={() => setMobileOpen(false)} /> : null}
    <div className={`min-h-screen transition-[padding] duration-200 ${collapsed ? "lg:pl-[72px]" : "lg:pl-64"}`}><header className="sticky top-0 z-10 flex h-16 items-center justify-between border-b border-line bg-canvas/90 px-4 backdrop-blur sm:px-6"><div className="flex items-center gap-2"><button type="button" className="rounded-md p-2 text-ink-muted hover:bg-ink/5 lg:hidden" aria-label="Open navigation" onClick={() => setMobileOpen(true)}><Menu size={19} /></button><button type="button" className="hidden rounded-md p-2 text-ink-muted hover:bg-ink/5 lg:inline-flex" aria-label="Toggle sidebar" onClick={toggleSidebar}><PanelLeft size={18} /></button><span className="hidden text-xs text-ink-muted sm:inline">Cognitive runtime / local observer</span></div><div className="flex items-center gap-3"><div className="flex items-center gap-2 text-xs text-ink-muted"><StatusDot status={runtimeStatus} />{runtimeStatus === "ready" ? "Ready" : runtimeStatus === "not_ready" ? "Offline" : "Connecting"}</div><ThemeToggle theme={theme} setTheme={setTheme} /></div></header><main className="mx-auto max-w-[1440px] px-4 py-6 sm:px-6 lg:px-8"><Outlet /></main></div>
  </div>;
}

function NavItem({ to, label, icon, collapsed, onNavigate }: { to: string; label: string; icon: JSX.Element; collapsed: boolean; onNavigate: () => void }): JSX.Element { return <Link to={to} activeOptions={{ exact: to === "/" }} activeProps={{ className: "bg-ink text-white shadow-sm dark:bg-white dark:text-ink" }} inactiveProps={{ className: "text-ink-muted hover:bg-ink/5 hover:text-ink dark:hover:bg-white/8" }} className={`group flex min-h-10 items-center gap-3 rounded-md px-3 text-sm font-semibold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-400/80 ${collapsed ? "justify-center px-2" : ""}`} title={collapsed ? label : undefined} onClick={onNavigate}>{icon}{collapsed ? <span className="sr-only">{label}</span> : <span>{label}</span>}</Link>; }
function FutureItem({ label, collapsed }: { label: string; collapsed: boolean }): JSX.Element { return <div aria-disabled="true" title={collapsed ? `${label} — coming later` : undefined} className={`flex min-h-10 items-center gap-3 rounded-md px-3 text-sm font-semibold text-ink-muted/45 ${collapsed ? "justify-center px-2" : ""}`}><CircleHelp size={17} /><span className={collapsed ? "sr-only" : ""}>{label}</span>{!collapsed ? <Badge>F3+</Badge> : null}</div>; }
function ThemeToggle({ theme, setTheme }: { theme: ThemePreference; setTheme: (theme: ThemePreference) => void }): JSX.Element { const next: Record<ThemePreference, ThemePreference> = { system: "dark", dark: "light", light: "system" }; return <button type="button" aria-label={`Theme: ${theme}. Switch theme`} title={`Theme: ${theme}`} onClick={() => setTheme(next[theme])} className="rounded-md p-2 text-ink-muted hover:bg-ink/5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-400/80">{theme === "light" ? <Sun size={17} /> : theme === "dark" ? <Moon size={17} /> : <span className="text-xs font-bold">SYS</span>}</button>; }

export function OverviewPage(): JSX.Element { const summary = useQuery({ queryKey: ["summary"], queryFn: api.summary, refetchInterval: 15_000 }); const sessions = useQuery({ queryKey: ["sessions", { limit: 5 }], queryFn: () => api.sessions({ limit: 5 }) }); return <div className="space-y-6"><PageIntro eyebrow="Runtime / overview" title="A live view of your cognitive runtime." detail="Open a conversation when you need to work; keep this page for a quick operational read." />{summary.isError ? <ErrorState message="Runtime summary unavailable. Check the server connection." onRetry={() => void summary.refetch()} /> : null}<div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Runtime status" value={summary.data?.status ?? "Loading"} detail={summary.data?.version ?? ""} tone={summary.data?.status === "ready" ? "success" : "warning"} /><StatCard label="Sessions" value={formatNumber(summary.data?.sessionsCount)} detail={`${formatNumber(summary.data?.activeSessions)} active`} /><StatCard label="Agents" value={formatNumber(summary.data?.activeAgents)} detail={`${formatNumber(summary.data?.registeredAgents)} registered`} /><StatCard label="Context limit" value={summary.data?.contextLimitTokens ? `${Math.round(summary.data.contextLimitTokens / 1024)}k` : "N/A"} detail="visible agent" /></div><Card><CardHeader><div className="flex items-center justify-between"><div><Label>Sessions</Label><h2 className="mt-1 text-lg font-semibold tracking-tight">Recent working sets</h2></div><Link className="text-xs font-semibold text-amber-600 hover:text-amber-500" to="/sessions">View all <ChevronRight className="inline" size={14} /></Link></div></CardHeader><CardBody className="p-0">{sessions.isLoading ? <div className="space-y-3 px-5 py-5"><Skeleton className="h-10" /><Skeleton className="h-10" /></div> : sessions.data?.items.length ? <div className="divide-y divide-line">{sessions.data.items.map((session) => <SessionRow key={session.id} session={session} />)}</div> : <EmptyState title="No sessions yet" detail="Create a conversation to begin." />}</CardBody></Card></div>; }

export function SessionsPage(): JSX.Element { const sessions = useQuery({ queryKey: ["sessions", { limit: 50 }], queryFn: () => api.sessions({ limit: 50 }) }); const navigate = useNavigate(); const queryClient = useQueryClient(); const create = useMutation({ mutationFn: () => api.createSession(), onSuccess: async (session) => { await queryClient.invalidateQueries({ queryKey: ["sessions"] }); await navigate({ to: "/sessions/$sessionId", params: { sessionId: session.id } }); } }); return <div className="space-y-6"><div className="flex flex-wrap items-end justify-between gap-4"><PageIntro eyebrow="Runtime / sessions" title="Conversations, not transcripts." detail="Each session maps to canonical History. Start a new working set or return to a previous one." /><Button onClick={() => create.mutate()} disabled={create.isPending}>{create.isPending ? "Creating…" : "New session"}</Button></div>{sessions.isLoading ? <div className="space-y-3"><Skeleton className="h-16" /><Skeleton className="h-16" /></div> : sessions.isError ? <ErrorState message="Sessions could not be loaded." onRetry={() => void sessions.refetch()} /> : sessions.data?.items.length ? <Card><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="border-b border-line bg-canvas/60 text-[11px] uppercase tracking-[0.13em] text-ink-muted"><tr><th className="px-5 py-3 font-semibold">Session</th><th className="px-5 py-3 font-semibold">Status</th><th className="px-5 py-3 font-semibold">Messages</th><th className="px-5 py-3 font-semibold">Updated</th><th className="px-5 py-3" /></tr></thead><tbody className="divide-y divide-line">{sessions.data.items.map((session) => <tr key={session.id} className="group hover:bg-ink/[0.025] dark:hover:bg-white/[0.025]"><td className="px-5 py-4"><Link to="/sessions/$sessionId" params={{ sessionId: session.id }} className="block font-semibold hover:text-amber-600 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-400/80"><span className="block">{session.displayName ?? "Untitled session"}</span><CopyableId value={session.id} /></Link></td><td className="px-5 py-4"><StatusBadge status={session.status} /></td><td className="px-5 py-4 font-mono text-xs text-ink-muted">{formatNumber(session.messageCount)}</td><td className="px-5 py-4 text-ink-muted">{formatRelative(session.updatedAt)}</td><td className="px-5 py-4 text-right"><Link to="/sessions/$sessionId" params={{ sessionId: session.id }} className="text-ink-muted opacity-0 transition-opacity group-hover:opacity-100 focus:opacity-100"><ExternalLink size={16} aria-label="Open session" /></Link></td></tr>)}</tbody></table></div></Card> : <EmptyState title="No sessions yet" detail="The runtime has no visible working sets." />}</div>; }

function SessionPage(): JSX.Element {
  const { sessionId } = useParams({ from: "/sessions/$sessionId" }); const queryClient = useQueryClient(); const navigate = useNavigate();
  const session = useQuery({ queryKey: ["session", sessionId], queryFn: () => api.session(sessionId) }); const messages = useQuery({ queryKey: ["messages", sessionId], queryFn: () => api.messages(sessionId, { limit: 1_000 }) }); const context = useQuery({ queryKey: ["context", sessionId], queryFn: () => api.context(sessionId), refetchInterval: 10_000 });
  const [draft, setDraft] = React.useState(""); const [generation, setGeneration] = React.useState<{ id: string; assistantId: string } | null>(null); const [streamText, setStreamText] = React.useState(""); const [streamStatus, setStreamStatus] = React.useState<"starting" | "streaming" | "completed" | "cancelled" | "failed" | null>(null); const [activities, setActivities] = React.useState<ChatActivity[]>([]); const [inspectorOpen, setInspectorOpen] = React.useState(false);
  const latestAssistantId = [...(messages.data?.items ?? [])].reverse().find((message) => message.role === "assistant")?.id;
  const retrieval = useQuery({ queryKey: ["retrieval", sessionId, latestAssistantId], queryFn: () => api.retrieval(sessionId, latestAssistantId!), enabled: Boolean(latestAssistantId), refetchInterval: 10_000 });
  React.useEffect(() => { if (!generation) return; const cleanup = subscribeToChatStream(sessionId, generation.id, (event) => handleChatEvent(event), (status) => { if (status === "error") setStreamStatus("failed"); }); return cleanup; }, [generation?.id, sessionId]);
  const send = useMutation({ mutationFn: (content: string) => api.sendMessage(sessionId, content), onSuccess: (result, content) => { setStreamText(""); setActivities([]); setStreamStatus("starting"); setGeneration({ id: result.generationId, assistantId: result.assistantMessageId }); setDraft(""); void queryClient.invalidateQueries({ queryKey: ["messages", sessionId] }); void queryClient.invalidateQueries({ queryKey: ["session", sessionId] }); }, });
  const retry = useMutation({ mutationFn: (messageId: string) => api.retryMessage(sessionId, messageId), onSuccess: (result) => { setStreamText(""); setActivities([]); setStreamStatus("starting"); setGeneration({ id: result.generationId, assistantId: result.assistantMessageId }); void queryClient.invalidateQueries({ queryKey: ["messages", sessionId] }); } });
  const stop = useMutation({ mutationFn: () => generation ? api.cancelGeneration(sessionId, generation.id) : Promise.resolve(undefined), });
  function handleChatEvent(event: ChatStreamEventDto): void { if (event.type === "started") setStreamStatus("streaming"); if (event.type === "text_delta") { setStreamStatus("streaming"); setStreamText((current) => current + (event.delta ?? "")); } if (event.type === "activity" && event.activity) setActivities((current) => [...current.slice(-3), event.activity!]); if (event.type === "completed" || event.type === "cancelled" || event.type === "failed") { setStreamStatus(event.type); setGeneration(null); void queryClient.invalidateQueries({ queryKey: ["messages", sessionId] }); void queryClient.invalidateQueries({ queryKey: ["session", sessionId] }); void queryClient.invalidateQueries({ queryKey: ["context", sessionId] }); void queryClient.invalidateQueries({ queryKey: ["retrieval", sessionId] }); } }
  function submit(): void { const value = draft.trim(); if (!value || send.isPending || generation) return; send.mutate(value); }
  if (session.isLoading || messages.isLoading) return <div className="space-y-4"><Skeleton className="h-8 w-64" /><Skeleton className="h-[520px]" /></div>;
  if (session.isError || messages.isError || !session.data || !messages.data) return <ErrorState message={session.error instanceof ApiClientError && session.error.code === "not_found" ? "Session not found." : "Conversation unavailable."} onRetry={() => { void session.refetch(); void messages.refetch(); }} />;
  const currentMessages = messages.data.items; const lastAssistant = [...currentMessages].reverse().find((message) => message.role === "assistant");
  return <div className="-mx-4 -my-6 sm:-mx-6 lg:-mx-8"><div className="grid min-h-[calc(100vh-4rem)] lg:grid-cols-[236px_minmax(0,1fr)_236px]">
    <ChatSidebar sessionId={sessionId} onNew={async () => { const created = await api.createSession(); await queryClient.invalidateQueries({ queryKey: ["sessions"] }); await navigate({ to: "/sessions/$sessionId", params: { sessionId: created.id } }); }} />
    <section className="flex min-w-0 flex-col border-x border-line bg-canvas"><div className="flex items-center justify-between border-b border-line px-4 py-3 sm:px-6"><div className="min-w-0"><Link to="/sessions" className="text-xs font-semibold text-ink-muted hover:text-ink">Sessions</Link><h1 className="mt-1 truncate text-lg font-semibold tracking-tight">{session.data.displayName ?? "Untitled session"}</h1></div><div className="flex items-center gap-2"><span className={`hidden text-xs sm:inline ${generation ? "text-amber-600" : "text-ink-muted"}`}>{generation ? "Generating" : "Ready"}</span><Button variant="outline" className="lg:hidden" onClick={() => setInspectorOpen(!inspectorOpen)}>{inspectorOpen ? "Hide details" : "Details"}</Button></div></div><div className="flex-1 overflow-y-auto px-4 py-6 sm:px-8"><div className="mx-auto max-w-3xl space-y-5">{currentMessages.length === 0 && !generation ? <EmptyState title="Start the conversation" detail="Ask Mnemos anything about the runtime. Your canonical History will appear here." /> : currentMessages.map((message) => <MessageBubble key={message.id} message={message} onRetry={message.role === "assistant" && message.status !== "streaming" ? () => retry.mutate(message.id) : undefined} />)}{generation ? <div data-testid="streaming-message" className="flex gap-3"><Avatar role="assistant" /><div className="min-w-0 flex-1 rounded-2xl rounded-tl-sm border border-amber-300/50 bg-amber-50/60 px-4 py-3 dark:bg-amber-300/5"><div className="mb-2 flex items-center gap-2 text-xs font-semibold text-amber-700 dark:text-amber-300">Mnemos <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-amber-500" />{streamStatus === "starting" ? "Starting" : "Streaming"}</div><MarkdownMessage text={streamText || "_Thinking through the runtime…_"} /><div className="mt-3 flex flex-wrap gap-2">{activities.map((activity, index) => <ActivityChip key={`${activity.kind}-${index}`} activity={activity} />)}</div></div></div> : null}</div></div><div className="border-t border-line bg-panel/80 px-4 py-4 sm:px-6"><div className="mx-auto max-w-3xl"><div className="flex items-end gap-2 rounded-xl border border-line bg-canvas p-2 shadow-sm focus-within:border-amber-400/80 focus-within:ring-2 focus-within:ring-amber-400/15"><label htmlFor="chat-composer" className="sr-only">Message Mnemos</label><textarea id="chat-composer" value={draft} disabled={Boolean(generation) || send.isPending} onChange={(event) => setDraft(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); submit(); } }} placeholder="Message Mnemos…" rows={2} className="min-h-12 max-h-40 min-w-0 flex-1 resize-y bg-transparent px-2 py-1 text-sm leading-6 outline-none placeholder:text-ink-muted/70" />{generation ? <Button variant="danger" aria-label="Stop generation" onClick={() => stop.mutate()} disabled={stop.isPending}><Square size={15} fill="currentColor" />Stop</Button> : <Button aria-label="Send message" onClick={submit} disabled={!draft.trim() || send.isPending}><Send size={15} />Send</Button>}</div><p className="mt-2 text-[11px] text-ink-muted">Enter to send · Shift+Enter for a new line · Runtime activity is summarized safely.</p>{send.isError ? <p className="mt-2 text-xs text-red-600">Message could not be sent. Try again.</p> : null}</div></div></section>
    <ContextInspector session={session.data} messages={currentMessages} activities={activities} context={context.data} retrieval={retrieval.data} open={inspectorOpen} />
  </div></div>;
}

function ChatSidebar({ sessionId, onNew }: { sessionId: string; onNew: () => Promise<void> }): JSX.Element { const sessions = useQuery({ queryKey: ["sessions", { limit: 50 }], queryFn: () => api.sessions({ limit: 50 }) }); return <aside className="hidden border-r border-line bg-panel lg:block"><div className="flex items-center justify-between border-b border-line px-4 py-3"><Label>Sessions</Label><Button variant="outline" className="h-8 px-2 text-xs" onClick={() => void onNew()}>New</Button></div><div className="space-y-1 p-2">{sessions.data?.items.map((session) => <Link key={session.id} to="/sessions/$sessionId" params={{ sessionId: session.id }} className={`block rounded-lg px-3 py-3 text-sm transition-colors ${session.id === sessionId ? "bg-amber-400/15 text-ink" : "text-ink-muted hover:bg-ink/5 hover:text-ink"}`}><span className="block truncate font-semibold">{session.displayName ?? "Untitled session"}</span><span className="mt-1 block text-xs text-ink-muted">{formatNumber(session.messageCount)} messages · {formatRelative(session.updatedAt)}</span></Link>)}</div></aside>; }
function Inspector({ session, messages, activities, open }: { session: SessionSummaryDto; messages: ChatMessageDto[]; activities: ChatActivity[]; open: boolean }): JSX.Element { const toolCalls = activities.filter((activity) => activity.kind === "tool").length; const ptcCalls = activities.filter((activity) => activity.kind === "ptc").length; return <aside className={`${open ? "block" : "hidden"} border-l border-line bg-panel lg:block`}><div className="border-b border-line px-4 py-3"><Label>Inspector</Label><h2 className="mt-1 text-sm font-semibold">Working summary</h2></div><div className="space-y-5 p-4"><div><p className="text-[11px] uppercase tracking-[0.14em] text-ink-muted">Current agent</p><p className="mt-1 text-sm font-semibold">visible.general</p></div><div><p className="text-[11px] uppercase tracking-[0.14em] text-ink-muted">Context pressure</p><div className="mt-2 flex items-center gap-2"><StatusDot status="ready" /><span className="text-sm font-semibold">NORMAL</span></div></div><dl className="grid grid-cols-2 gap-3"><InspectorStat label="Messages" value={messages.length} /><InspectorStat label="Memory" value={activities.some((activity) => activity.kind === "memory") ? 1 : 0} /><InspectorStat label="Tool calls" value={toolCalls} /><InspectorStat label="PTC calls" value={ptcCalls} /></dl><div className="border-t border-line pt-4"><p className="text-[11px] uppercase tracking-[0.14em] text-ink-muted">Session</p><CopyableId value={session.id} /></div></div></aside>; }
function ContextInspector({ session, messages, activities, context, retrieval, open }: { session: SessionSummaryDto; messages: ChatMessageDto[]; activities: ChatActivity[]; context?: ContextInspectorDto; retrieval?: RetrievalInspectorDto; open: boolean }): JSX.Element {
  const stats = context?.stats; const toolCalls = activities.filter((activity) => activity.kind === "tool").length; const ptcCalls = activities.filter((activity) => activity.kind === "ptc").length;
  const rows = stats ? [["System", stats.systemTokens], ["Pinned", stats.pinnedTokens], ["Recent raw", stats.recentRawTokens], ["Retrieved memory", stats.retrievedMemoryTokens], ["Tool results", stats.toolResultTokens], ["Tool schemas", stats.toolSchemaTokens], ["Artifact handles", stats.artifactHandleTokens]] as const : [];
  return <aside className={`${open ? "block" : "hidden"} max-h-[calc(100vh-4rem)] overflow-y-auto border-l border-line bg-panel lg:block`}><div className="border-b border-line px-4 py-3"><Label>Inspector / F3</Label><h2 className="mt-1 text-sm font-semibold">Context working set</h2></div><div className="space-y-5 p-4"><div className="flex items-center justify-between"><div><p className="text-[11px] uppercase tracking-[0.14em] text-ink-muted">Pressure</p><p className="mt-1 text-lg font-semibold">{stats?.pressureLevel ?? "Loading…"}</p></div><Badge tone={stats?.pressureLevel === "EMERGENCY" ? "danger" : stats?.pressureLevel === "NORMAL" ? "success" : "warning"}>{stats ? `${Math.round(stats.pressure * 100)}%` : "—"}</Badge></div>{stats ? <><div className="h-2 overflow-hidden rounded-full bg-ink/10 dark:bg-white/10"><div className="h-full rounded-full bg-amber-400 transition-[width]" style={{ width: `${Math.min(100, stats.pressure * 100)}%` }} /></div><dl className="grid grid-cols-2 gap-2 text-xs"><InspectorStat label="Used" value={stats.usedTokens} /><InspectorStat label="Safe headroom" value={stats.safeHeadroomTokens} /><InspectorStat label="Reserve" value={stats.generationReserveTokens} /><InspectorStat label="Recent target" value={stats.recentRawTargetTokens} /></dl><div className="space-y-2"><div className="flex items-center justify-between"><Label>Token composition</Label><span className="font-mono text-[10px] text-ink-muted">{formatNumber(stats.usedTokens)} / {formatNumber(stats.contextLimit)}</span></div>{rows.map(([label, value]) => <TokenRow key={label} label={label} value={value} limit={stats.contextLimit} />)}</div><div><Label>Policy</Label><div className="mt-2 flex flex-wrap gap-1.5">{context.policy.recommendations.map((action) => <Badge key={action} tone={context.policy.enforced ? "danger" : "neutral"}>{action.replaceAll("_", " ")}</Badge>)}</div></div></> : <Skeleton className="h-40" />}{retrieval?.results.length ? <div className="border-t border-line pt-4"><div className="flex items-center justify-between"><Label>Retrieved memory</Label><Link to="/memory" className="text-[11px] font-semibold text-amber-600">Explore</Link></div>{retrieval.results.map((result) => <div key={result.memory.id} className="mt-2 rounded-lg border border-line bg-canvas/60 p-2.5"><div className="flex items-center justify-between gap-2"><span className="text-xs font-semibold">#{result.rank} {result.memory.type}</span><span className="font-mono text-[10px] text-ink-muted">{result.score.toFixed(2)}</span></div><p className="mt-1 text-xs leading-5">{result.memory.content}</p><p className="mt-1 text-[10px] text-ink-muted">matched by {result.matchedBy.join(" + ")}</p></div>)}</div> : null}<div><Label>Pins</Label><div className="mt-2 space-y-1.5">{context?.pins.map((pin) => <div key={pin.id} className="rounded-lg border border-line bg-canvas/50 p-2"><div className="flex items-center justify-between gap-2"><span className="text-xs font-semibold">{pin.source}</span><span className="font-mono text-[10px] text-ink-muted">{formatNumber(pin.tokenEstimate)} tok</span></div><p className="mt-1 text-[11px] leading-4 text-ink-muted">{pin.contentPreview}</p></div>)}</div></div><div><Label>Compaction timeline</Label><div className="mt-2 space-y-2">{context?.compactions.map((entry) => <div key={entry.id} className="rounded-lg border border-line p-2.5"><div className="flex items-center justify-between"><span className="text-xs font-semibold">{entry.kind} boundary</span><span className="text-[10px] text-ink-muted">{formatRelative(entry.createdAt)}</span></div><p className="mt-1 text-[11px] text-ink-muted">{formatNumber(entry.beforeTokens)} → {formatNumber(entry.afterTokens)} tokens · {entry.evictedMessageCount} messages evicted</p><Link to="/sessions/$sessionId/history/$messageId" params={{ sessionId: session.id, messageId: entry.cutoffAfterMessageId }} className="mt-2 inline-flex items-center gap-1 text-[11px] font-semibold text-amber-600">View canonical History <ExternalLink size={12} /></Link></div>)}</div></div><div className="border-t border-line pt-4"><dl className="grid grid-cols-2 gap-2"><InspectorStat label="Messages" value={messages.length} /><InspectorStat label="Memory" value={context?.retrievedMemoryCount ?? 0} /><InspectorStat label="Tool calls" value={toolCalls} /><InspectorStat label="PTC calls" value={ptcCalls} /></dl><CopyableId value={session.id} /></div></div></aside>;
}
function TokenRow({ label, value, limit }: { label: string; value: number; limit: number }): JSX.Element { return <div><div className="mb-1 flex justify-between text-[11px]"><span className="text-ink-muted">{label}</span><span className="font-mono">{formatNumber(value)}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-ink/10 dark:bg-white/10"><div className="h-full rounded-full bg-ink/40 dark:bg-white/40" style={{ width: `${Math.min(100, (value / Math.max(1, limit)) * 100)}%` }} /></div></div>; }
function InspectorStat({ label, value }: { label: string; value: number }): JSX.Element { return <div className="rounded-lg border border-line bg-canvas/60 p-3"><p className="text-lg font-semibold">{formatNumber(value)}</p><p className="mt-1 text-[11px] text-ink-muted">{label}</p></div>; }

function MessageBubble({ message, onRetry }: { message: ChatMessageDto; onRetry?: () => void }): JSX.Element { const user = message.role === "user"; return <div className={`flex gap-3 ${user ? "justify-end" : ""}`}><Avatar role={message.role} /><div className={`min-w-0 max-w-[min(100%,44rem)] rounded-2xl px-4 py-3 ${user ? "rounded-tr-sm bg-ink text-white dark:bg-white dark:text-ink" : "rounded-tl-sm border border-line bg-panel"}`}><div className="mb-2 flex items-center gap-2 text-xs font-semibold opacity-70">{user ? "You" : "Mnemos"}<span>{formatRelative(message.createdAt)}</span>{message.status !== "completed" ? <Badge tone={message.status === "failed" ? "danger" : "warning"}>{message.status}</Badge> : null}</div><MarkdownMessage text={message.content || (message.status === "streaming" ? "_Streaming…_" : "")} dark={user} />{onRetry && (message.status === "failed" || message.status === "cancelled") ? <button type="button" onClick={onRetry} className="mt-3 inline-flex items-center gap-1 text-xs font-semibold underline decoration-dotted underline-offset-4 opacity-75 hover:opacity-100">Retry</button> : null}</div></div>; }
function Avatar({ role }: { role: ChatMessageDto["role"] }): JSX.Element { return <span className={`mt-1 grid h-7 w-7 shrink-0 place-items-center rounded-lg text-[10px] font-black ${role === "user" ? "bg-amber-400 text-ink" : "bg-ink text-amber-300 dark:bg-white dark:text-ink"}`}>{role === "user" ? "U" : "M"}</span>; }
function ActivityChip({ activity }: { activity: ChatActivity }): JSX.Element { return <span className="inline-flex items-center gap-1.5 rounded-full border border-amber-300/40 bg-amber-100/50 px-2 py-1 text-[11px] font-medium text-amber-800 dark:bg-amber-300/10 dark:text-amber-200"><Activity size={11} />{activity.label}</span>; }

export function MarkdownMessage({ text, dark = false }: { text: string; dark?: boolean }): JSX.Element { return <div className={`markdown-message text-sm leading-7 ${dark ? "text-inherit" : "text-ink"}`}>{renderMarkdown(text)}</div>; }
function renderMarkdown(text: string): JSX.Element[] { const lines = text.split("\n"); const blocks: JSX.Element[] = []; let index = 0; while (index < lines.length) { const line = lines[index]; if (line.startsWith("```")) { const language = line.slice(3).trim() || "text"; const code: string[] = []; index += 1; while (index < lines.length && !lines[index].startsWith("```")) code.push(lines[index++]); index += 1; blocks.push(<CodeBlock key={`code-${index}`} language={language} value={code.join("\n")} />); continue; } if (!line.trim()) { index += 1; continue; } if (line.startsWith("#")) { const level = Math.min(line.match(/^#+/)?.[0].length ?? 1, 3); blocks.push(React.createElement(`h${level}`, { key: `h-${index}`, className: "mt-3 text-base font-semibold tracking-tight" }, inlineMarkdown(line.slice(level).trim()))); index += 1; continue; } if (/^[-*] /.test(line)) { const items: string[] = []; while (index < lines.length && /^[-*] /.test(lines[index])) items.push(lines[index++].slice(2)); blocks.push(<ul key={`ul-${index}`} className="my-2 list-disc space-y-1 pl-5">{items.map((item, itemIndex) => <li key={itemIndex}>{inlineMarkdown(item)}</li>)}</ul>); continue; } if (/^\d+\. /.test(line)) { const items: string[] = []; while (index < lines.length && /^\d+\. /.test(lines[index])) items.push(lines[index++].replace(/^\d+\. /, "")); blocks.push(<ol key={`ol-${index}`} className="my-2 list-decimal space-y-1 pl-5">{items.map((item, itemIndex) => <li key={itemIndex}>{inlineMarkdown(item)}</li>)}</ol>); continue; } if (line.includes("|") && index + 1 < lines.length && /^\s*\|?\s*:?-{3,}/.test(lines[index + 1])) { const headers = splitTable(line); index += 2; const rows: string[][] = []; while (index < lines.length && lines[index].includes("|")) rows.push(splitTable(lines[index++])); blocks.push(<div key={`table-${index}`} className="my-3 overflow-x-auto"><table className="min-w-full border-collapse text-left text-xs"><thead><tr>{headers.map((header) => <th key={header} className="border border-line bg-canvas/70 px-2 py-1 font-semibold">{inlineMarkdown(header)}</th>)}</tr></thead><tbody>{rows.map((row, rowIndex) => <tr key={rowIndex}>{row.map((cell, cellIndex) => <td key={cellIndex} className="border border-line px-2 py-1">{inlineMarkdown(cell)}</td>)}</tr>)}</tbody></table></div>); continue; } const paragraph: string[] = [line]; index += 1; while (index < lines.length && lines[index].trim() && !lines[index].startsWith("```") && !/^[-*] /.test(lines[index]) && !/^\d+\. /.test(lines[index])) paragraph.push(lines[index++]); blocks.push(<p key={`p-${index}`} className="my-2">{inlineMarkdown(paragraph.join(" "))}</p>); } return blocks; }
function splitTable(line: string): string[] { return line.trim().replace(/^\|/, "").replace(/\|$/, "").split("|").map((cell) => cell.trim()); }
function inlineMarkdown(value: string): React.ReactNode[] { const parts = value.split(/(`[^`]+`|\[[^\]]+\]\([^\)]+\)|\*\*[^*]+\*\*)/g).filter(Boolean); return parts.map((part, index) => part.startsWith("`") ? <code key={index} className="rounded bg-ink/10 px-1.5 py-0.5 font-mono text-[0.88em]">{part.slice(1, -1)}</code> : part.startsWith("[") ? <a key={index} href={part.match(/^\[([^\]]+)\]\(([^\)]+)\)$/)?.[2] ?? "#"} target="_blank" rel="noreferrer" className="text-amber-600 underline underline-offset-2">{part.match(/^\[([^\]]+)/)?.[1] ?? part}</a> : part.startsWith("**") ? <strong key={index}>{part.slice(2, -2)}</strong> : <React.Fragment key={index}>{part}</React.Fragment>); }
function CodeBlock({ language, value }: { language: string; value: string }): JSX.Element { const [copied, setCopied] = React.useState(false); return <div className="my-3 overflow-hidden rounded-lg border border-line bg-[#171817] text-[#f2f0e8]"><div className="flex items-center justify-between border-b border-white/10 px-3 py-2 text-[10px] uppercase tracking-[0.14em] text-white/55"><span>{language}</span><button type="button" className="inline-flex items-center gap-1 rounded px-2 py-1 hover:bg-white/10" onClick={() => { void navigator.clipboard?.writeText(value); setCopied(true); setTimeout(() => setCopied(false), 1200); }}><Copy size={12} />{copied ? "Copied" : "Copy"}</button></div><pre className="max-w-full overflow-x-auto p-3 font-mono text-xs leading-6"><code>{value}</code></pre></div>; }

export function MemoryPage(): JSX.Element {
  const [draft, setDraft] = React.useState(""); const [query, setQuery] = React.useState(""); const [type, setType] = React.useState(""); const [status, setStatus] = React.useState(""); const [selectedId, setSelectedId] = React.useState<string | null>(null);
  const page = useQuery({ queryKey: ["memory", query, type, status], queryFn: () => api.memorySearch({ query, ...(type ? { type: type as "semantic" } : {}), ...(status ? { status: status as "active" } : {}), limit: 50 }) });
  const detail = useQuery({ queryKey: ["memory-detail", selectedId], queryFn: () => api.memory(selectedId!), enabled: Boolean(selectedId) }); const sources = useQuery({ queryKey: ["memory-sources", selectedId], queryFn: () => api.memorySources(selectedId!), enabled: Boolean(selectedId) });
  return <div className="space-y-6"><PageIntro eyebrow="Runtime / memory" title="Trace long-term memory back to History." detail="Search derived memories, inspect their confidence and lifecycle, then follow every source to canonical conversation text." /><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_420px]"><Card><CardHeader><form className="flex flex-wrap gap-2" onSubmit={(event) => { event.preventDefault(); setQuery(draft.trim()); }}><label htmlFor="memory-search" className="sr-only">Search memory</label><input id="memory-search" value={draft} onChange={(event) => setDraft(event.target.value)} placeholder="Search facts, entities, tags…" className="h-10 min-w-[220px] flex-1 rounded-md border border-line bg-canvas px-3 text-sm outline-none focus:border-amber-400" /><select aria-label="Memory type" value={type} onChange={(event) => setType(event.target.value)} className="h-10 rounded-md border border-line bg-canvas px-2 text-xs"><option value="">All types</option><option value="semantic">Semantic</option><option value="decision">Decision</option><option value="episodic">Episodic</option><option value="preference">Preference</option></select><select aria-label="Memory status" value={status} onChange={(event) => setStatus(event.target.value)} className="h-10 rounded-md border border-line bg-canvas px-2 text-xs"><option value="">All status</option><option value="active">Active</option><option value="superseded">Superseded</option><option value="archived">Archived</option></select><Button type="submit"><Search size={15} />Search</Button></form></CardHeader><CardBody className="p-0">{page.isLoading ? <div className="space-y-3 p-5"><Skeleton className="h-20" /><Skeleton className="h-20" /></div> : page.isError ? <div className="p-5"><ErrorState message="Memory index unavailable." onRetry={() => void page.refetch()} /></div> : page.data?.items.length ? <div className="divide-y divide-line">{page.data.items.map((memory) => <button type="button" key={memory.id} onClick={() => setSelectedId(memory.id)} className={`block w-full px-5 py-4 text-left transition-colors hover:bg-ink/[0.025] ${selectedId === memory.id ? "bg-amber-400/10" : ""}`}><div className="flex items-center justify-between gap-3"><div className="flex items-center gap-2"><Badge tone={memory.status === "active" ? "success" : memory.status === "superseded" ? "warning" : "neutral"}>{memory.status}</Badge><span className="text-xs font-semibold">{memory.type}</span></div><span className="font-mono text-[10px] text-ink-muted">{Math.round(memory.confidence * 100)}% confidence</span></div><p className="mt-2 text-sm leading-6">{memory.content}</p><div className="mt-2 flex flex-wrap gap-1.5 text-[10px] text-ink-muted">{memory.entities.map((entity) => <span key={entity}>#{entity}</span>)}<span>· {memory.sourceReferences.length} sources</span>{memory.stale ? <span>· stale</span> : null}</div></button>)}</div> : <div className="p-8"><EmptyState title="No matching memory" detail="Try a broader query or clear a lifecycle filter." /></div>}</CardBody></Card><Card><CardHeader><Label>Memory detail</Label><h2 className="mt-1 text-lg font-semibold">{detail.data?.type ?? "Select a record"}</h2></CardHeader><CardBody>{detail.isLoading ? <Skeleton className="h-40" /> : detail.data ? <div className="space-y-4"><p className="text-sm leading-6">{detail.data.content}</p><dl className="grid grid-cols-2 gap-3 text-xs"><Definition label="Confidence" value={`${Math.round(detail.data.confidence * 100)}%`} /><Definition label="Reinforcement" value={`${Math.round(detail.data.reinforcementScore * 100)}%`} /><Definition label="Confirmations" value={detail.data.confirmationCount} /><Definition label="Scope" value={`${detail.data.scope.kind}:${detail.data.scope.id}`} /><Definition label="Status" value={detail.data.status} /><Definition label="Source type" value={detail.data.sourceType} /></dl>{detail.data.supersededBy ? <p className="rounded-md bg-amber-400/10 px-3 py-2 text-xs">Superseded by <button type="button" className="font-semibold text-amber-700" onClick={() => setSelectedId(detail.data!.supersededBy!)}>{detail.data.supersededBy}</button></p> : null}<div><Label>Provenance</Label><div className="mt-2 space-y-2">{(sources.data ?? []).map((source) => <Link key={source.messageId} to="/sessions/$sessionId/history/$messageId" params={{ sessionId: source.sessionId, messageId: source.messageId }} className="block rounded-lg border border-line p-2.5 hover:border-amber-400"><div className="flex justify-between text-[11px]"><span className="font-semibold">{source.role} · source {source.ordinal + 1}</span><span className="text-ink-muted">{formatRelative(source.createdAt)}</span></div><p className="mt-1 text-xs leading-5 text-ink-muted">{source.content}</p></Link>)}</div></div><div><Label>Timeline</Label><div className="mt-2 space-y-1">{detail.data.timeline.map((entry) => <div key={entry.id} className="flex items-center justify-between text-xs"><span>{entry.status} · {entry.content.slice(0, 52)}{entry.content.length > 52 ? "…" : ""}</span><span className="font-mono text-[10px] text-ink-muted">{Math.round(entry.confidence * 100)}%</span></div>)}</div></div></div> : <EmptyState title="Choose a memory" detail="The selected record's lifecycle and source references will appear here." />}</CardBody></Card></div></div>;
}

export function HistorySourcePage(): JSX.Element { const { sessionId, messageId } = useParams({ from: "/sessions/$sessionId/history/$messageId" }); const source = useQuery({ queryKey: ["history", sessionId, messageId], queryFn: () => api.historyMessage(sessionId, messageId) }); return <div className="mx-auto max-w-3xl space-y-6"><Link to="/sessions/$sessionId" params={{ sessionId }} className="inline-flex items-center gap-2 text-xs font-semibold text-ink-muted hover:text-ink"><ArrowLeft size={14} />Back to session</Link><PageIntro eyebrow="Canonical History" title="Original message" detail="This is the source record behind a derived memory or compaction boundary. It is read-only." />{source.isLoading ? <Skeleton className="h-48" /> : source.data ? <Card><CardHeader><div className="flex items-center justify-between"><div><Badge tone={source.data.role === "user" ? "success" : "neutral"}>{source.data.role}</Badge><p className="mt-2 font-mono text-[11px] text-ink-muted">{source.data.id}</p></div><span className="text-xs text-ink-muted">{formatDate(source.data.createdAt)}</span></div></CardHeader><CardBody><MarkdownMessage text={source.data.content} /><div className="mt-6 flex justify-between border-t border-line pt-4 text-xs">{source.data.beforeId ? <Link to="/sessions/$sessionId/history/$messageId" params={{ sessionId, messageId: source.data.beforeId }} className="font-semibold text-amber-600">← Previous</Link> : <span />}{source.data.afterId ? <Link to="/sessions/$sessionId/history/$messageId" params={{ sessionId, messageId: source.data.afterId }} className="font-semibold text-amber-600">Next →</Link> : null}</div></CardBody></Card> : <ErrorState message="Canonical History message not found." onRetry={() => void source.refetch()} />}</div>; }

export function EventsPage(): JSX.Element { const filter = useUiStore((state) => state.eventFilter); const paused = useUiStore((state) => state.eventsPaused); const setFilter = useUiStore((state) => state.setEventFilter); const setPaused = useUiStore((state) => state.setEventsPaused); const events = useLiveEvents(500, paused); const filtered = filter === "all" ? events.events : events.events.filter((event) => event.type === filter); return <div className="space-y-6"><PageIntro eyebrow="Runtime / events" title="The runtime pulse, safely summarized." detail="Chat text has its own stream; this view remains a bounded metadata-only debug buffer." /><Card><CardHeader><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><StatusDot status={events.status} /><span className="text-sm font-semibold capitalize">{events.status}</span>{paused ? <Badge tone="warning">UI paused</Badge> : null}</div><div className="flex flex-wrap items-center gap-2"><label className="sr-only" htmlFor="event-filter">Filter events</label><select id="event-filter" value={filter} onChange={(event) => setFilter(event.target.value)} className="h-9 rounded-md border border-line bg-panel px-3 text-sm"><option value="all">All event types</option>{[...new Set(events.events.map((event) => event.type))].map((type) => <option key={type} value={type}>{type}</option>)}</select><Button variant="outline" onClick={() => setPaused(!paused)}>{paused ? "Resume" : "Pause"}</Button><Button variant="quiet" onClick={events.clear}>Clear</Button></div></div></CardHeader><CardBody className="p-0">{filtered.length === 0 ? <div className="px-5 py-12"><EmptyState title="No events in this view" detail="Keep the stream open while the runtime changes." /></div> : <div className="max-h-[620px] overflow-auto">{filtered.map((event) => <EventRow key={event.id} event={event} detailed />)}</div>}</CardBody></Card></div>; }
function SettingsPage(): JSX.Element { const summary = useQuery({ queryKey: ["summary"], queryFn: api.summary }); return <div className="space-y-6"><PageIntro eyebrow="Runtime / settings" title="Read-only configuration summary." detail="Operational controls stay outside the Console. Secrets and raw environment values are never exposed here." /><Card><CardBody><dl className="grid gap-x-8 gap-y-5 sm:grid-cols-2"><Definition label="Profile" value={summary.data?.profile ?? "N/A"} /><Definition label="Context default" value={summary.data?.contextLimitTokens ? `${formatNumber(summary.data.contextLimitTokens)} tokens` : "N/A"} /><Definition label="Sandbox backend" value={summary.data?.sandboxBackend ?? "N/A"} /><Definition label="Database path" value="Hidden" /></dl></CardBody></Card></div>; }

function PageIntro({ eyebrow, title, detail }: { eyebrow: string; title: string; detail: React.ReactNode }): JSX.Element { return <div className="max-w-3xl"><Label>{eyebrow}</Label><h1 className="mt-2 text-3xl font-semibold tracking-[-0.04em] sm:text-4xl">{title}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-ink-muted sm:text-base">{detail}</p></div>; }
function StatCard({ label, value, detail, tone = "neutral" }: { label: string; value: string; detail: string; tone?: "neutral" | "success" | "warning" }): JSX.Element { return <Card className="overflow-hidden"><CardBody className="relative"><div className={`absolute inset-x-0 top-0 h-0.5 ${tone === "success" ? "bg-emerald-400" : tone === "warning" ? "bg-amber-400" : "bg-ink/10 dark:bg-white/15"}`} /><Label>{label}</Label><p className="mt-3 truncate text-2xl font-semibold tracking-tight">{value}</p><p className="mt-1 text-xs text-ink-muted">{detail}</p></CardBody></Card>; }
function SessionRow({ session }: { session: SessionSummaryDto }): JSX.Element { return <Link to="/sessions/$sessionId" params={{ sessionId: session.id }} className="flex items-center justify-between gap-4 px-5 py-4 transition-colors hover:bg-ink/[0.025] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-amber-400/80"><div className="min-w-0"><p className="truncate text-sm font-semibold">{session.displayName ?? "Untitled session"}</p><div className="mt-1 flex items-center gap-2"><CopyableId value={session.id} /><span className="text-xs text-ink-muted">{formatNumber(session.messageCount)} messages</span></div></div><StatusBadge status={session.status} /></Link>; }
function EventRow({ event, detailed = false }: { event: RuntimeEventDto; detailed?: boolean }): JSX.Element { return <div className="flex gap-3 border-b border-line px-5 py-3 last:border-b-0"><span className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-amber-400" /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-x-2"><span className="font-mono text-xs font-semibold">{event.type}</span><span className="text-[11px] text-ink-muted">{formatRelative(event.timestamp)}</span></div>{detailed ? <pre className="mt-2 max-w-full overflow-x-auto rounded-md bg-canvas p-3 font-mono text-[11px] leading-5 text-ink-muted">{JSON.stringify(event.payload, null, 2)}</pre> : null}</div></div>; }
function Definition({ label, value }: { label: string; value: React.ReactNode }): JSX.Element { return <div><dt className="text-xs text-ink-muted">{label}</dt><dd className="mt-1 text-sm font-semibold">{value}</dd></div>; }
function NotFoundPage(): JSX.Element { const navigate = useNavigate(); return <div className="mx-auto max-w-xl py-20 text-center"><Label>404 / route not found</Label><h1 className="mt-3 text-3xl font-semibold">This page is not part of F2.</h1><Button className="mt-6" onClick={() => void navigate({ to: "/" })}>Back to overview</Button></div>; }
function useLiveEvents(limit: number, paused = false): { events: RuntimeEventDto[]; status: "live" | "reconnecting" | "disconnected"; clear: () => void } { const [events, setEvents] = React.useState<RuntimeEventDto[]>([]); const [status, setStatus] = React.useState<"live" | "reconnecting" | "disconnected">("reconnecting"); const [pending, setPending] = React.useState<RuntimeEventDto[]>([]); React.useEffect(() => subscribeToEvents((event) => paused ? setPending((current) => [event, ...current].slice(0, limit)) : setEvents((current) => [event, ...current].slice(0, limit)), setStatus), [limit, paused]); React.useEffect(() => { if (!paused && pending.length) { setEvents((current) => [...pending, ...current].slice(0, limit)); setPending([]); } }, [paused]); return { events, status, clear: () => { setEvents([]); setPending([]); } }; }
